function validate([words]) {
  if (!Array.isArray(words) || words.length < 1 || words.length > 1000) return 'words needs 1 to 1000 strings.';
  if (words.some(w => typeof w !== 'string' || !/^[a-z]{1,20}$/.test(w))) return 'Each word has 1 to 20 lowercase letters.';
  if (words.some(w => w.length !== words[0].length)) return 'All words must have the same length.';
  return null;
}

