function numSpecialEquivGroups(words) {
  const groups = new Set();
  for (const word of words) {
    const count = new Array(52).fill(0);
    for (let i = 0; i < word.length; i++) {
      const letter = word.charCodeAt(i) - 97;
      count[letter + 26 * (i % 2)]++;
    }
    groups.add(count.join(','));
  }
  return groups.size;
}

