function numSpecialEquivGroups(words) {
  // Sort the even-index and odd-index letters of each word, then compare each word with one member of every group so far.
  const sortedHalves = word => {
    const even = [], odd = [];
    for (let i = 0; i < word.length; i++) (i % 2 === 0 ? even : odd).push(word[i]);
    return [even.sort().join(''), odd.sort().join('')];
  };
  const representatives = [];
  for (const word of words) {
    const [even, odd] = sortedHalves(word);
    if (!representatives.some(([e, o]) => e === even && o === odd)) representatives.push([even, odd]);
  }
  return representatives.length;
}

