function generate(rand, size) {
  const pick = n => Math.floor(rand() * n);
  const n = size === 'large' ? 800 + pick(201) : 1 + pick(8);
  const length = size === 'large' ? [2, 6, 20][pick(3)] : 1 + pick(5);
  const alphabet = 'abcdefghijklmnopqrstuvwxyz'.slice(0, [2, 3, 26][pick(3)]);
  const randomWord = () => Array.from({ length }, () => alphabet[pick(alphabet.length)]).join('');
  // Shuffle the even positions among themselves and the odd positions among themselves.
  const scramble = word => {
    const chars = word.split('');
    for (const start of [0, 1]) {
      const idx = [];
      for (let i = start; i < length; i += 2) idx.push(i);
      for (let a = idx.length - 1; a > 0; a--) {
        const b = pick(a + 1);
        [chars[idx[a]], chars[idx[b]]] = [chars[idx[b]], chars[idx[a]]];
      }
    }
    return chars.join('');
  };
  const bases = Array.from({ length: 1 + pick(size === 'large' ? 60 : 4) }, randomWord);
  const words = [];
  for (let k = 0; k < n; k++) {
    words.push(rand() < 0.75 ? scramble(bases[pick(bases.length)]) : randomWord());
  }
  return [words];
}
